@msig trait SupervisoryStatusAssessment_governorProcess_supervisoryStatusAssessment_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment)
  }

  /** helper function to set the values of all input ports.
   * @param decisionSnapshot payload for data port decisionSnapshot
   * @param batteryQualification payload for data port batteryQualification
   */
  def put_concrete_inputs(decisionSnapshot : Drone_Lifecycle_Governor.DecisionSnapshot,
                          batteryQualification : Drone_Lifecycle_Governor.BatteryQualification.Type): Unit = {
    put_decisionSnapshot(decisionSnapshot)
    put_batteryQualification(batteryQualification)
  }


  /** helper function to check SupervisoryStatusAssessment_governorProcess_supervisoryStatusAssessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param pilotStatus method that will be called with the value of the outgoing data
   *        port 'pilotStatus'.
   */
  def check_concrete_output(pilotStatus: Drone_Lifecycle_Governor.PilotStatus => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val pilotStatusValue: Drone_Lifecycle_Governor.PilotStatus = get_pilotStatus().get
    if(!pilotStatus(pilotStatusValue)) {
      testFailures = testFailures :+ st"'pilotStatus' did not match expected: value of the outgoing data port is ${pilotStatusValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_decisionSnapshot(value : Drone_Lifecycle_Governor.DecisionSnapshot): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment.operational_api.decisionSnapshot_Id, Drone_Lifecycle_Governor.DecisionSnapshot_Payload(value))
  }

  // setter for in DataPort
  def put_batteryQualification(value : Drone_Lifecycle_Governor.BatteryQualification.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment.operational_api.batteryQualification_Id, Drone_Lifecycle_Governor.BatteryQualification_Payload(value))
  }

  // getter for out DataPort
  def get_pilotStatus(): Option[Drone_Lifecycle_Governor.PilotStatus] = {
    val value: Option[Drone_Lifecycle_Governor.PilotStatus] = get_pilotStatus_payload() match {
      case Some(Drone_Lifecycle_Governor.PilotStatus_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port pilotStatus.  Expecting 'Drone_Lifecycle_Governor.PilotStatus_Payload' but received ${v}")
      case _ => None[Drone_Lifecycle_Governor.PilotStatus]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_pilotStatus_payload(): Option[Drone_Lifecycle_Governor.PilotStatus_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_supervisoryStatusAssessment.initialization_api.pilotStatus_Id).asInstanceOf[Option[Drone_Lifecycle_Governor.PilotStatus_Payload]]
  }

}
